  "sql": "WITH _base AS (\n  SELECT\n    regions.name AS \"customers.regions.name\",\n    COUNT(*) AS \"customers.count_all\",\n    CAST(SUM(customers.credit) AS DOUBLE) AS \"customers.sum_credit\"\n  FROM customers AS customers\n  LEFT JOIN regions AS regions\n    ON customers.region_id = regions.id\n  GROUP BY\n    regions.name\n), _cm_customers__orders__id_count AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    COUNT(orders.id) AS \"orders.id_count\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  GROUP BY\n    customers__regions.name\n)\nSELECT\n  _base.\"customers.regions.name\",\n  _base.\"customers.count_all\",\n  _base.\"customers.sum_credit\",\n  COALESCE(_cm_customers__orders__id_count.\"orders.id_count\", 0) AS \"customers.count_orders_id\"\nFROM _base\nLEFT JOIN _cm_customers__orders__id_count\n  ON _base.\"customers.regions.name\" IS NOT DISTINCT FROM _cm_customers__orders__id_count.\"orders.customers.regions.name\"\nORDER BY\n  _base.\"customers.regions.name\" ASC\nLIMIT 101"
